/**
 * Admin preview pane: the annotated screenshot of the section being edited
 * (public/admin/huong-dan/, numbered ①②③ like the field labels), then the
 * text being typed under the same numbers. Data: huong-dan/guide.js,
 * generated by scripts/admin-guide.mjs. `h` is React's createElement,
 * provided by Sveltia CMS.
 */
const h = window.h;

CMS.registerPreviewStyle(`
  .hn { font: 15px/1.5 system-ui, sans-serif; color: #1f2a24; }
  .hn-note { margin: 0 0 8px; color: #5b6660; font-size: 13px; }
  .hn-shot { display: block; border: 1px solid #d9dcd6; border-radius: 6px; overflow: hidden; margin-bottom: 20px; }
  .hn-shot img { display: block; width: 100%; height: auto; }
  .hn-field { padding: 10px 0; border-top: 1px solid #e6e8e3; }
  .hn-label { font-weight: 700; font-size: 13px; color: #5b6660; margin-bottom: 4px; }
  .hn-value { white-space: pre-line; }
`, { raw: true });

for (const [name, guide] of Object.entries(window.ADMIN_GUIDE ?? {})) {
  CMS.registerPreviewTemplate(name, ({ widgetFor }) =>
    h('div', { className: 'hn' },
      h('p', { className: 'hn-note' }, 'Phần này trên website. Số trên ảnh khớp với số ở tên từng ô bên trái. Bấm vào ảnh để mở trang.'),
      h('a', { className: 'hn-shot', href: guide.url, target: '_blank', rel: 'noopener' },
        h('img', { src: `/admin/${guide.image}`, alt: '' })),
      ...guide.fields.map(([field, label]) =>
        h('div', { className: 'hn-field', key: field },
          h('div', { className: 'hn-label' }, label),
          h('div', { className: 'hn-value' }, widgetFor(field)))),
    ));
}
